              const dataUrl = await new Promise((resolve) => {
                reader.onload = (e) => resolve(e.target?.result);
                reader.readAsDataURL(file);
              });
              externalActors.push({
                id: diskId,
                url: dataUrl,
                tag: "front",
                // Default for single files
                name: displayName,
                profile: {
                  identity,
                  wardrobe: "",
                  accessories: "",
                  style: "External Asset"
                }
              });
